(R/'FINAL_REPORT.md').write_text('\n'.join(text)+'\n');assert json.loads((R/'parameter_identity.json').read_text())['equal'];assert all(hashlib.sha256((R/p).read_bytes()).hexdigest()==v for p,v in json.loads((R/'frozen_sources.json').read_text())['files'].items());assert not any(v['passed'] for v in analysis['confirmation'].values());(R/'final_verification.json').write_text(json.dumps(dict(passed=True,weights_unchanged=True,frozen_sources_unchanged=True,confirmation_topics=8,isolated_phase_control_pass=False),indent=2))
